func (f *bundleFreezer) m5(x map[string]*Route) {
	cnfrt.GrowPool(&f.c1, len(x))
	cnfrt.GrowPool(&f.c2, cnfrt.HashRegion(len(x)))
	if len(x) == 0 {
		return
	}
	var keys []string
	cacheLarge := len(x) >= 256
	if cacheLarge {
		keys = make([]string, 0, len(x))
	} else {
		keys = f.k5[:0]
		f.k5 = nil
		if cap(keys) < len(x) {
			keys = make([]string, 0, max(len(x), 2*cap(keys)))
		}
	}
	for k := range x {
		keys = append(keys, k)
	}
	slices.Sort(keys)
	if cacheLarge {
		f.cached5 = append(f.cached5, keys)
	}
	for _, k := range keys {
		f.b.MeasureString(string(k))
		v := x[k]
		f.mn2(v)
	}
	if !cacheLarge {
		f.k5 = keys[:0]
	}
}

func (f *bundleFreezer) e5(x map[string]*Route) cnfrt.HashSpan {
	if x == nil {
		return cnfrt.HashSpan{KV: cnfrt.NilSpan, Idx: cnfrt.NilSpan}
	}
	n := len(x)
	if n == 0 {
		return cnfrt.HashSpan{}
	}
	var keys []string
	reuseBuf := true
	if n >= 256 {
		if f.cachedPos5 >= len(f.cached5) {
			cnfrt.Fail(cnfrt.ErrConcurrentModification)
		}
		keys = f.cached5[f.cachedPos5]
		f.cached5[f.cachedPos5] = nil
		f.cachedPos5++
		if len(keys) != n {
			cnfrt.Fail(cnfrt.ErrConcurrentModification)
		}
		reuseBuf = false
	} else {
		// Take the shared key buffer; a nested map of the same type finds it
		// empty and uses its own.
		keys = f.k5[:0]
		f.k5 = nil
		if cap(keys) < n {
			keys = make([]string, 0, max(n, 2*cap(keys)))
		}
		for k := range x {
			keys = append(keys, k)
		}
		if len(keys) != n {
			cnfrt.Fail(cnfrt.ErrConcurrentModification)
		}
		slices.Sort(keys)
	}
	off := f.reserve(&f.p1, f.c1, n)
	dst := f.s.pool1[off : int(off)+n]
	for i, k := range keys {
		v, ok := x[k]
		if !ok {
			cnfrt.Fail(cnfrt.ErrConcurrentModification)
		}
		dst[i].K = f.b.String(string(k))
		dst[i].V = f.en2(v)
	}
	region := cnfrt.HashRegion(n)
	ioff := f.reserve(&f.p2, f.c2, region)
	idx := f.s.pool2[ioff : int(ioff)+region]
	mask := uint64(region - 1)
	for i, k := range keys {
		h := cnfrt.HashString(string(k), f.b.Seed)
		for j := h & mask; ; j = (j + 1) & mask {
			if idx[j] == 0 {
				idx[j] = uint32(i + 1)
				break
			}
		}
	}
	if reuseBuf {
		f.k5 = keys[:0]
	}
	return cnfrt.HashSpan{KV: cnfrt.Span32{Off: off, Len: uint32(n)}, Idx: cnfrt.Span32{Off: ioff, Len: uint32(region)}}
}

