// trackBundleSnapshot registers a snapshot that owns its string blob (a frozen
// snapshot or one loaded from a private copy) with the leak detector.
func trackBundleSnapshot(s *BundleSnapshot, err error) (*BundleSnapshot, error) {
	if err != nil {
		return nil, err
	}
	s.leak = cnfrt.TrackSnapshot(cnfrt.GlobalLeakDetector(), s, "BundleSnapshot", s.strBlob, true)
	return s, nil
}

// trackSharedBundleSnapshot registers a snapshot whose string blob aliases memory it
// does not own (a mapping or a caller's buffer); only the snapshot itself
// is watched.
func trackSharedBundleSnapshot(s *BundleSnapshot, err error) (*BundleSnapshot, error) {
	if err != nil {
		return nil, err
	}
	s.leak = cnfrt.TrackSnapshot(cnfrt.GlobalLeakDetector(), s, "BundleSnapshot", s.strBlob, false)
	return s, nil
}

// FreezeBundle freezes the object graph rooted at src into a snapshot.
// Shared pointers are deduplicated and directed cycles are rejected with
// cnfrt.ErrCycleDetected.
func FreezeBundle(src *Bundle, opts ...cnfrt.FreezeOption) (*BundleSnapshot, error) {
	return trackBundleSnapshot(freezeBundle(cnfrt.ModeDAG, src, opts))
}

// FreezeTreeBundle freezes src as a tree: no visited set is kept (shared
// pointers are duplicated) and recursion deeper than the maximum depth fails
// with cnfrt.ErrCycleDetected. Because addresses are not recorded, src does
// not need to escape to the heap.
func FreezeTreeBundle(src *Bundle, opts ...cnfrt.FreezeOption) (*BundleSnapshot, error) {
	return trackBundleSnapshot(freezeTreeBundle(src, opts))
}

// FreezeCyclicBundle freezes src permitting directed cycles; shared pointers are
// deduplicated.
func FreezeCyclicBundle(src *Bundle, opts ...cnfrt.FreezeOption) (*BundleSnapshot, error) {
	return trackBundleSnapshot(freezeBundle(cnfrt.ModeCyclic, src, opts))
}

func freezeBundle(mode cnfrt.FreezeMode, src *Bundle, opts []cnfrt.FreezeOption) (snap *BundleSnapshot, err error) {
	if src == nil {
		return nil, cnfrt.ErrNilRoot
	}
	cnfrt.Escape(src)
	f := bundleFreezerPool.Get().(*bundleFreezer)
	defer func() {
		cnfrt.Recover(recover(), &err)
		if err != nil {
			snap = nil
		}
		f.reset()
		bundleFreezerPool.Put(f)
	}()
	f.b.Init(mode, 9, opts...)
	f.mn0(src)
	f.allocate()
	id := f.en0(src)
	f.finish()
	runtime.KeepAlive(src)
	s := f.s
	s.rootTable, s.rootID = 0, id
	return s, nil
}

func freezeTreeBundle(src *Bundle, opts []cnfrt.FreezeOption) (snap *BundleSnapshot, err error) {
	if src == nil {
		return nil, cnfrt.ErrNilRoot
	}
	f := bundleFreezerPool.Get().(*bundleFreezer)
	defer func() {
		cnfrt.Recover(recover(), &err)
		if err != nil {
			snap = nil
		}
		f.reset()
		bundleFreezerPool.Put(f)
	}()
	f.b.Init(cnfrt.ModeTree, 9, opts...)
	f.mn0(src)
	f.allocate()
	id := f.en0(src)
	f.finish()
	runtime.KeepAlive(src)
	s := f.s
	s.rootTable, s.rootID = 0, id
	return s, nil
}

