func (s *BundleSnapshot) validate() error {
	v := &bundleValidator{s: s, cyclic: s.flags&cnfrt.FlagCyclicAllowed != 0, claims: make([]cnfrt.Claims, 9), workBudget: 32*uint64(s.SizeBytes()) + 65536}
	for _, a := range s.zoned {
		v.workBudget += 32 * uint64(len(a.Zone()))
	}
	if s.dict != nil {
		// Strings of an allowed Dict are compared during validation too;
		// their budget stays linear in the dictionary size.
		v.workBudget += min(32*s.dict.Stats().Bytes, 64<<20)
	}
	v.claims[0] = cnfrt.NewClaims(len(s.pool0))
	v.claims[1] = cnfrt.NewClaims(len(s.pool1))
	v.claims[2] = cnfrt.NewClaims(len(s.pool2))
	v.claims[3] = cnfrt.NewClaims(len(s.pool3))
	v.claims[4] = cnfrt.NewClaims(len(s.pool4))
	v.claims[5] = cnfrt.NewClaims(len(s.pool5))
	v.claims[6] = cnfrt.NewClaims(len(s.pool6))
	v.claims[7] = cnfrt.NewClaims(len(s.pool7))
	v.claims[8] = cnfrt.NewClaims(len(s.pool8))
	for i := range s.nodesBundle {
		v.row0(&s.nodesBundle[i], uint32(i+1))
		if v.err != nil {
			return v.err
		}
	}
	for i := range s.nodesPolicy {
		v.row1(&s.nodesPolicy[i], uint32(i+1))
		if v.err != nil {
			return v.err
		}
	}
	for i := range s.nodesRoute {
		v.row2(&s.nodesRoute[i], uint32(i+1))
		if v.err != nil {
			return v.err
		}
	}
	for i := range s.nodesPathPrefix {
		v.row3(&s.nodesPathPrefix[i], uint32(i+1))
		if v.err != nil {
			return v.err
		}
	}
	for i := range s.nodesHeaderEquals {
		v.row4(&s.nodesHeaderEquals[i], uint32(i+1))
		if v.err != nil {
			return v.err
		}
	}
	for i := range s.nodesSourceIn {
		v.row5(&s.nodesSourceIn[i], uint32(i+1))
		if v.err != nil {
			return v.err
		}
	}
	for i := range s.nodesMethodIn {
		v.row6(&s.nodesMethodIn[i], uint32(i+1))
		if v.err != nil {
			return v.err
		}
	}
	for i := range s.nodesNot {
		v.row7(&s.nodesNot[i], uint32(i+1))
		if v.err != nil {
			return v.err
		}
	}
	for i := range s.nodesRateLimit {
		v.row8(&s.nodesRateLimit[i], uint32(i+1))
		if v.err != nil {
			return v.err
		}
	}
	return nil
}

func (s *BundleSnapshot) appendSections(secs []cnfrt.Section) []cnfrt.Section {
	if len(s.nodesBundle) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionTable, ElemAlign: 8, Tag: 0, Count: uint32(len(s.nodesBundle)), Data: cnfrt.ViewSliceLE(s.nodesBundle)})
	}
	if len(s.nodesPolicy) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionTable, ElemAlign: 4, Tag: 1, Count: uint32(len(s.nodesPolicy)), Data: cnfrt.ViewSliceLE(s.nodesPolicy)})
	}
	if len(s.nodesRoute) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionTable, ElemAlign: 4, Tag: 2, Count: uint32(len(s.nodesRoute)), Data: cnfrt.ViewSliceLE(s.nodesRoute)})
	}
	if len(s.nodesPathPrefix) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionTable, ElemAlign: 4, Tag: 3, Count: uint32(len(s.nodesPathPrefix)), Data: cnfrt.ViewSliceLE(s.nodesPathPrefix)})
	}
	if len(s.nodesHeaderEquals) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionTable, ElemAlign: 4, Tag: 4, Count: uint32(len(s.nodesHeaderEquals)), Data: cnfrt.ViewSliceLE(s.nodesHeaderEquals)})
	}
	if len(s.nodesSourceIn) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionTable, ElemAlign: 4, Tag: 5, Count: uint32(len(s.nodesSourceIn)), Data: cnfrt.ViewSliceLE(s.nodesSourceIn)})
	}
	if len(s.nodesMethodIn) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionTable, ElemAlign: 4, Tag: 6, Count: uint32(len(s.nodesMethodIn)), Data: cnfrt.ViewSliceLE(s.nodesMethodIn)})
	}
	if len(s.nodesNot) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionTable, ElemAlign: 4, Tag: 7, Count: uint32(len(s.nodesNot)), Data: cnfrt.ViewSliceLE(s.nodesNot)})
	}
	if len(s.nodesRateLimit) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionTable, ElemAlign: 8, Tag: 8, Count: uint32(len(s.nodesRateLimit)), Data: cnfrt.ViewSliceLE(s.nodesRateLimit)})
	}
	if len(s.pool0) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionPool, ElemAlign: 4, Tag: 0, Count: uint32(len(s.pool0)), Data: cnfrt.ViewSliceLE(s.pool0)})
	}
	if len(s.pool1) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionPool, ElemAlign: 4, Tag: 1, Count: uint32(len(s.pool1)), Data: cnfrt.ViewSliceLE(s.pool1)})
	}
	if len(s.pool2) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionPool, ElemAlign: 4, Tag: 2, Count: uint32(len(s.pool2)), Data: cnfrt.ViewSliceLE(s.pool2)})
	}
	if len(s.pool3) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionPool, ElemAlign: 1, Tag: 3, Count: uint32(len(s.pool3)), Data: cnfrt.ViewSliceLE(s.pool3)})
	}
	if len(s.pool4) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionPool, ElemAlign: 4, Tag: 4, Count: uint32(len(s.pool4)), Data: cnfrt.ViewSliceLE(s.pool4)})
	}
	if len(s.pool5) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionPool, ElemAlign: 4, Tag: 5, Count: uint32(len(s.pool5)), Data: cnfrt.ViewSliceLE(s.pool5)})
	}
	if len(s.pool6) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionPool, ElemAlign: 4, Tag: 6, Count: uint32(len(s.pool6)), Data: cnfrt.ViewSliceLE(s.pool6)})
	}
	if len(s.pool7) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionPool, ElemAlign: 4, Tag: 7, Count: uint32(len(s.pool7)), Data: cnfrt.ViewSliceLE(s.pool7)})
	}
	if len(s.pool8) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionPool, ElemAlign: 4, Tag: 8, Count: uint32(len(s.pool8)), Data: cnfrt.ViewSliceLE(s.pool8)})
	}
	if len(s.strBlob) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionStrBlob, ElemAlign: 1, Count: uint32(len(s.strBlob)), Data: cnfrt.UnsafeStringBytes(s.strBlob)})
	}
	if ext := cnfrt.EncodeExt(s.locEntries, s.zoned); ext != nil {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionExt, ElemAlign: 4, Count: uint32(len(ext)), Data: ext})
	}
	return secs
}

func (s *BundleSnapshot) sections() []cnfrt.Section {
	return s.appendSections(make([]cnfrt.Section, 0, 20))
}

func (s *BundleSnapshot) header(extra uint32) cnfrt.Header {
	return cnfrt.Header{Flags: s.flags | extra, SchemaHash: SchemaHashBundle, HashSeed: s.seed, RootTable: s.rootTable, RootID: s.rootID}
}

// WriteTo writes the snapshot as a .cnf image to w. It returns
// cnfrt.ErrClosed if s is a closed memory-mapped snapshot, or
// cnfrt.ErrDictRequired if s references a process-local cnfrt.Dict.
func (s *BundleSnapshot) WriteTo(w io.Writer) (int64, error) {
	if s.mapping != nil && s.mapping.Closed() {
		return 0, cnfrt.ErrClosed
	}
	if s.flags&cnfrt.FlagHasDict != 0 {
		return 0, cnfrt.ErrDictRequired
	}
	var secBuf [20]cnfrt.Section
	n, err := cnfrt.WriteImage(w, s.header(0), s.appendSections(secBuf[:0]))
	runtime.KeepAlive(s)
	return n, err
}

// MarshalCNF returns the snapshot encoded as a .cnf image. It returns
// cnfrt.ErrClosed if s is a closed memory-mapped snapshot, or
// cnfrt.ErrDictRequired if s references a process-local cnfrt.Dict.
func (s *BundleSnapshot) MarshalCNF() ([]byte, error) {
	if s.mapping != nil && s.mapping.Closed() {
		return nil, cnfrt.ErrClosed
	}
	if s.flags&cnfrt.FlagHasDict != 0 {
		return nil, cnfrt.ErrDictRequired
	}
	var secBuf [20]cnfrt.Section
	h, secs := s.header(0), s.appendSections(secBuf[:0])
	out, err := cnfrt.AppendImage(make([]byte, 0, cnfrt.ImageSize(h, secs)), h, secs)
	runtime.KeepAlive(s)
	return out, err
}

// WriteBundleSnapshotAtomic writes s to path atomically (temporary file, fsync, rename,
// directory fsync), so concurrent MapBundleFile calls never observe a partial
// file.
func WriteBundleSnapshotAtomic(path string, s *BundleSnapshot) error {
	return cnfrt.WriteSnapshotAtomic(path, func(w io.Writer) error {
		_, err := s.WriteTo(w)
		return err
	})
}

// MapBundleFile memory-maps the .cnf file at path read-only and returns a
// snapshot over it. With cnfrt.VerifyTrustedHeader only the header and
// section geometry are checked; cnfrt.VerifyChecksum also verifies all
// section checksums. cnfrt.VerifyUntrusted copies the file to the heap,
// unmaps it and validates every reference, so arbitrary input is safe to
// read; the returned snapshot is then not memory-mapped.
//
// String getters of memory-mapped snapshots return copies. The mapping is
// released by Close or, failing that, when the snapshot becomes unreachable.
func MapBundleFile(path string, mode cnfrt.VerifyMode) (*BundleSnapshot, error) {
	m, err := unsafemmap.Open(path)
	if err != nil {
		return nil, err
	}
	if mode >= cnfrt.VerifyUntrusted {
		var data []byte
		err := unsafemmap.FaultSafe(func() error {
			data = cnfrt.AlignedCopy(m.Bytes())
			return nil
		})
		if cerr := m.Close(); err == nil {
			err = cerr
		}
		if err != nil {
			return nil, err
		}
		return trackBundleSnapshot(loadBundleSnapshot(data, mode))
	}
	var s *BundleSnapshot
	err = unsafemmap.FaultSafe(func() (err error) {
		s, err = loadBundleSnapshot(m.Bytes(), mode)
		return err
	})
	if err != nil {
		m.Close()
		return nil, err
	}
	mapped := m.IsMapped()
	s.mapping, s.isMmap, s.cloneStrs = m, mapped, mapped
	unsafemmap.AttachCleanup(s, m)
	return trackSharedBundleSnapshot(s, nil)
}

// UnmarshalBundleSnapshot decodes a .cnf image. Tables and strings of the result alias
// data, which must not be modified while the snapshot is in use, except with
// cnfrt.VerifyUntrusted, which validates an aligned private copy.
func UnmarshalBundleSnapshot(data []byte, mode cnfrt.VerifyMode) (*BundleSnapshot, error) {
	if mode >= cnfrt.VerifyUntrusted {
		return trackBundleSnapshot(loadBundleSnapshot(cnfrt.AlignedCopy(data), mode))
	}
	return trackSharedBundleSnapshot(loadBundleSnapshot(data, mode))
}

func loadBundleSnapshot(data []byte, mode cnfrt.VerifyMode) (*BundleSnapshot, error) {
	h, infos, err := cnfrt.ParseHeader(data, mode, SchemaHashBundle)
	if err != nil {
		return nil, err
	}
	return buildBundleSnapshot(data, h, infos, mode)
}

// buildBundleSnapshot assembles a snapshot from the parsed sections of an image.
func buildBundleSnapshot(data []byte, h cnfrt.Header, infos []cnfrt.SectionInfo, mode cnfrt.VerifyMode) (*BundleSnapshot, error) {
	var err error
	s := &BundleSnapshot{flags: h.Flags, seed: h.HashSeed, rootTable: h.RootTable, rootID: h.RootID}
	for _, in := range infos {
		switch {
		case in.Kind == cnfrt.SectionTable && in.Tag == 0:
			s.nodesBundle, err = unsafemmap.Cast[flatBundle](data, in)
		case in.Kind == cnfrt.SectionTable && in.Tag == 1:
			s.nodesPolicy, err = unsafemmap.Cast[flatPolicy](data, in)
		case in.Kind == cnfrt.SectionTable && in.Tag == 2:
			s.nodesRoute, err = unsafemmap.Cast[flatRoute](data, in)
		case in.Kind == cnfrt.SectionTable && in.Tag == 3:
			s.nodesPathPrefix, err = unsafemmap.Cast[flatPathPrefix](data, in)
		case in.Kind == cnfrt.SectionTable && in.Tag == 4:
			s.nodesHeaderEquals, err = unsafemmap.Cast[flatHeaderEquals](data, in)
		case in.Kind == cnfrt.SectionTable && in.Tag == 5:
			s.nodesSourceIn, err = unsafemmap.Cast[flatSourceIn](data, in)
		case in.Kind == cnfrt.SectionTable && in.Tag == 6:
			s.nodesMethodIn, err = unsafemmap.Cast[flatMethodIn](data, in)
		case in.Kind == cnfrt.SectionTable && in.Tag == 7:
			s.nodesNot, err = unsafemmap.Cast[flatNot](data, in)
		case in.Kind == cnfrt.SectionTable && in.Tag == 8:
			s.nodesRateLimit, err = unsafemmap.Cast[flatRateLimit](data, in)
		case in.Kind == cnfrt.SectionPool && in.Tag == 0:
			s.pool0, err = unsafemmap.Cast[uint32](data, in)
		case in.Kind == cnfrt.SectionPool && in.Tag == 1:
			s.pool1, err = unsafemmap.Cast[flatKVStringRouteHashMap](data, in)
		case in.Kind == cnfrt.SectionPool && in.Tag == 2:
			s.pool2, err = unsafemmap.Cast[uint32](data, in)
		case in.Kind == cnfrt.SectionPool && in.Tag == 3:
			s.pool3, err = unsafemmap.Cast[cnfrt.FlatPrefix](data, in)
		case in.Kind == cnfrt.SectionPool && in.Tag == 4:
			s.pool4, err = unsafemmap.Cast[flatKVStringPrefixSliceMap](data, in)
		case in.Kind == cnfrt.SectionPool && in.Tag == 5:
			s.pool5, err = unsafemmap.Cast[flatRule](data, in)
		case in.Kind == cnfrt.SectionPool && in.Tag == 6:
			s.pool6, err = unsafemmap.Cast[cnfrt.Span32](data, in)
		case in.Kind == cnfrt.SectionPool && in.Tag == 7:
			s.pool7, err = unsafemmap.Cast[flatKVStringStringMap](data, in)
		case in.Kind == cnfrt.SectionPool && in.Tag == 8:
			s.pool8, err = unsafemmap.Cast[cnfrt.VariantTag](data, in)
		case in.Kind == cnfrt.SectionStrBlob && in.Tag == 0:
			s.strBlob = unsafemmap.String(data, in)
		case in.Kind == cnfrt.SectionExt && in.Tag == 0:
			s.locEntries, s.zoned, err = cnfrt.DecodeExt(cnfrt.SectionData(data, in))
			s.locs = (&cnfrt.LocTable{Entries: s.locEntries}).Locations()
		default:
			err = fmt.Errorf("%w: unexpected section kind %d tag %d", cnfrt.ErrCorruptHeader, in.Kind, in.Tag)
		}
		if err != nil {
			return nil, err
		}
	}
	switch s.rootTable {
	case 0:
		if s.rootID == 0 || uint64(s.rootID) > uint64(len(s.nodesBundle)) {
			return nil, fmt.Errorf("%w: root ID %d", cnfrt.ErrBoundsViolation, s.rootID)
		}
	default:
		return nil, fmt.Errorf("%w: root table %d", cnfrt.ErrSchemaMismatch, s.rootTable)
	}
	if mode >= cnfrt.VerifyUntrusted {
		if err := s.validate(); err != nil {
			return nil, err
		}
	}
	return s, nil
}
